actions.script:
if (System.getProperty('purchase.pricing.qa.disposable')!='true' || !ec.user.isInGroup('ADMIN')) {
    ec.web.response.setStatus(403); ec.web.sendJsonResponse([denied:true]); return
}
if (ec.entity.find('mantle.party.Party').condition('partyId','PP_QA_A').disableAuthz().count()) {
    ec.web.response.setStatus(409); ec.web.sendJsonResponse([denied:true]); return
}
ec.entity.makeDataLoader().location('component://zenith-erp-purchase/VendorBillQaFixture.xml').load()
if(ec.message.hasError() || !ec.entity.find('mantle.product.Product').condition('productId','PP_QA_PRODUCT_A').disableAuthz().one()) {
    throw new IllegalStateException('Fixture load failed; refuse stale-state verification')
}
def demo=ec.entity.find('moqui.security.UserAccount').condition('userId','EX_JOHN_DOE').one()
def user=ec.entity.find('moqui.security.UserAccount').condition('userId','PP_QA_USER').one()
['currentPassword','passwordSalt','passwordHashType','passwordBase64'].each {user.set(it,demo.get(it))}
user.disabled='N'; user.requirePasswordChange='N'; user.update()
ec.web.sendJsonResponse([initialized:true])

if(System.getProperty('purchase.pricing.qa.disposable')!='true' || ec.user.username!='purchase.pricing.qa'){
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def calls=[
    create:['zenith.purchase.PurchaseServices.create#PurchaseInvoice',['organizationPartyId','vendorPartyId','vendorInvoiceNumber','invoiceDate','currencyUomId','purchaseOrderNumber','isImportPurchase','isReverseCharge','isCompositionDealer','itcEligible']],
    item:['zenith.purchase.PurchaseServices.add#PurchaseInvoiceItem',['invoiceId','productId','quantity','unitAmount','discountPercent','productTaxCode']],
    charged:['zenith.india.GstServices.get#ChargedInvoiceTax',['invoiceId']],
    gstr2:['zenith.india.Gstr2Services.generate#Gstr2Data',['organizationPartyId','returnPeriod']],
    gstr3b:['zenith.india.Gstr2Services.generate#Gstr3bData',['organizationPartyId','returnPeriod']]
]
def call=calls[ec.web.parameters.op];if(!call){ec.web.response.setStatus(400);ec.web.sendJsonResponse([denied:true]);return}
def params=[:];call[1].each {if(ec.web.parameters.containsKey(it))params[it]=ec.web.parameters[it]}
ec.message.clearErrors();def result=ec.service.sync().name(call[0]).parameters(params).call()
def errors=ec.message.hasError() ? [ec.message.getErrorsString()] : [];ec.message.clearErrors()
ec.web.sendJsonResponse([result:result,errors:errors])

if(System.getProperty('purchase.pricing.qa.disposable')!='true' || ec.user.username!='purchase.pricing.qa' ||
    ec.user.getPreference('ACTIVE_ORGANIZATION')!='PP_QA_A' || !(ec.web.parameters.scheme in ['Y','N'])) {
    ec.web.response.setStatus(403);ec.web.sendJsonResponse([denied:true]);return
}
def config=ec.entity.find('zenith.erp.india.IndiaGstConfig').condition('organizationPartyId','PP_QA_A').one()
if(!config) throw new IllegalStateException('Missing exact disposable buyer config')
config.isCompositionScheme=ec.web.parameters.scheme;config.update()
ec.web.sendJsonResponse([scheme:config.isCompositionScheme])

if(System.getProperty('purchase.pricing.qa.disposable')!='true' || !ec.user.isInGroup('ADMIN')) {
    ec.web.response.setStatus(403); ec.web.sendJsonResponse([denied:true]); return
}
def fixture=new groovy.xml.XmlParser().parseText(ec.resource.getLocationText('component://zenith-erp-purchase/VendorBillQaFixture.xml',false))
int removed=0
// Resolve the stored composite keys; seed timestamps use the initializing user's timezone.
ec.entity.find('moqui.security.UserGroupMember').condition('userId','PP_QA_USER').disableAuthz().list().each { it.delete();removed++ }
def bills=ec.entity.find('mantle.account.invoice.Invoice').condition('toPartyId','in',['PP_QA_A','PP_QA_B','PP_QA_VENDOR_A']).disableAuthz().list()
bills.each { bill ->
    ec.entity.find('zenith.erp.tax.TaxLineDetail').condition('referenceType','InvoiceItem').condition('referenceId',bill.invoiceId).disableAuthz().list().each { it.delete();removed++ }
    ec.entity.find('mantle.account.invoice.InvoiceItem').condition('invoiceId',bill.invoiceId).disableAuthz().list().each { it.delete();removed++ }
    bill.delete();removed++
}
fixture.children().reverse().each { node ->
    def entityName=node.name().toString()
    def pkFields=ec.entity.getEntityDefinition(entityName).getPkFieldNames()
    def keys=[:]
    pkFields.each {field ->
        def raw=node.attribute(field)
        if(raw!=null) keys[field]=(field=='fromDate' ? java.sql.Timestamp.valueOf(raw.toString().replace('T',' ')) : raw.toString())
    }
    if(!keys.values().any {it.toString().startsWith('PP_QA_')}) throw new IllegalStateException('Refusing non-fixture cleanup')
    def value=ec.entity.find(entityName).condition(keys).disableAuthz().one()
    if(value!=null) {value.delete(); removed++}
}
ec.web.sendJsonResponse([removed:removed])
